package ktanesolver.module.modded.regular.colourcode;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.SolveSuccess;
class ColourCodeSolverTest{@Test void calculatesAndInterleavesAllSevenItems(){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");b.setAaBatteryCount(2);ModuleEntity self=new ModuleEntity();self.setType(ModuleType.COLOUR_CODE);b.setModules(List.of(self));@SuppressWarnings("unchecked")ColourCodeOutput o=((SolveSuccess<ColourCodeOutput>)new ColourCodeSolver().solve(new RoundEntity(),b,self,new ColourCodeInput("purple",8,18))).output();assertThat(o.digits()).hasSize(4);assertThat(o.colors()).hasSize(3);assertThat(o.sequence()).hasSize(7);assertThat(o.entryCommand()).startsWith("press ").contains("s");assertThat(o.submitCommand()).startsWith("go");}}
